def format_bytes(n):
    """Convert bytes into a human-readable size.

    Args:
        n (int): Number of bytes

    Returns:
        str: Human-readable size, e.g., '1.5 KB', '1.2 MB', etc.
    """
    if n < 0:
        raise ValueError('n must be non-negative')

    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if n < 1024.0:
            return f"{n:.1f} {unit}"
        n /= 1024'
